import Phaser from 'phaser'
import SceneKeys from '~/consts/SceneKeys'
import MinesweeperBoard, { RevealResult } from '~/game/MinesweeperBoard'

type CellView = {
	bg: Phaser.GameObjects.Rectangle
	label: Phaser.GameObjects.Text
	flag: Phaser.GameObjects.Text
}

type GridPreset = {
	id: 'desktop' | 'mobile'
	label: string
	cols: number
	rows: number
	mines: number
	/** Default-Zellgröße; kann zur Laufzeit noch herunter skaliert werden, damit alles ins Canvas passt. */
	cellSize: number
}

export default class MainGame extends Phaser.Scene {
	private board!: MinesweeperBoard
	private cellViews: CellView[][] = []
	private statusText!: Phaser.GameObjects.Text
	private infoText!: Phaser.GameObjects.Text
	private gameOver = false

	// --- Grid-Konfiguration (wird über Presets gesetzt) ---
	private readonly presets: GridPreset[] = [
		{ id: 'desktop', label: 'Desktop', cols: 16, rows: 16, mines: 40, cellSize: 34 },
		// Smartphone: etwas kleineres Feld + größere Zellen, aber wir skalieren notfalls automatisch runter.
		{ id: 'mobile', label: 'Mobile', cols: 10, rows: 14, mines: 22, cellSize: 42 }
	]
	private selectedPresetId: GridPreset['id'] = 'desktop'

	private cols = 16
	private rows = 16
	private mines = 40
	private cellSize = 34
	private boardOffsetX = 40
	private boardOffsetY = 90

	// UI
	private presetButtons: Record<GridPreset['id'], Phaser.GameObjects.Text> | null = null
	private presetButtonsY = 0

	constructor() {
		super(SceneKeys.GAME)
	}

	create() {
		this.input.mouse?.disableContextMenu()

		const centerX = this.scale.width / 2

		this.statusText = this.add
			.text(centerX, 20, 'Minesweeper Rewired', {
				fontFamily: 'system-ui, -apple-system, Segoe UI, Roboto, Arial',
				fontSize: '28px',
				color: '#e2e8f0'
			})
			.setOrigin(0.5, 0)
			.setDepth(10)

		this.infoText = this.add
			.text(centerX, 55, 'Left Mouse: Reveal | Right Mouse: Set Flag | R: Reset', {
				fontFamily: 'system-ui, -apple-system, Segoe UI, Roboto, Arial',
				fontSize: '16px',
				color: '#94a3b8'
			})
			.setOrigin(0.5, 0)
			.setDepth(10)

		this.createPresetUi()

		// Preset initial anwenden + Game starten
		this.applyPreset(this.selectedPresetId)
		this.startNewGame()

		this.input.keyboard?.on('keydown-R', () => this.startNewGame())
	}

	private createPresetUi() {
		const centerX = this.scale.width / 2

		// Buttons immer unter die Info-Zeile legen, damit es keine Überlappung gibt.
		// (InfoText y=55, originY=0 => Unterkante ~= y + height)
		const infoBottom = this.infoText.y + this.infoText.height
		const y = Math.round(infoBottom + 18)
		this.presetButtonsY = y

		const buttonStyle: Phaser.Types.GameObjects.Text.TextStyle = {
			fontFamily: 'system-ui, -apple-system, Segoe UI, Roboto, Arial',
			fontSize: '14px',
			color: '#cbd5e1'
		}

		const desktopBtn = this.add
			.text(centerX - 70, y, 'Desktop', buttonStyle)
			.setOrigin(0.5, 0.5)
			.setPadding(10, 6, 10, 6)
			.setDepth(10)
			.setInteractive({ useHandCursor: true })
			.on('pointerup', () => this.onSelectPreset('desktop'))

		const mobileBtn = this.add
			.text(centerX + 70, y, 'Mobile', buttonStyle)
			.setOrigin(0.5, 0.5)
			.setPadding(10, 6, 10, 6)
			.setDepth(10)
			.setInteractive({ useHandCursor: true })
			.on('pointerup', () => this.onSelectPreset('mobile'))

		this.presetButtons = { desktop: desktopBtn, mobile: mobileBtn }
		this.updatePresetUi()
	}

	private onSelectPreset(id: GridPreset['id']) {
		if (this.selectedPresetId === id) return
		this.selectedPresetId = id
		this.applyPreset(id)
		this.updatePresetUi()
		this.startNewGame()
	}

	private updatePresetUi() {
		if (!this.presetButtons) return

		for (const preset of this.presets) {
			const btn = this.presetButtons[preset.id]
			const isSelected = preset.id === this.selectedPresetId
			btn.setStyle({
				backgroundColor: isSelected ? '#334155' : '#1f2937',
				color: isSelected ? '#e2e8f0' : '#cbd5e1'
			})
			btn.setAlpha(isSelected ? 1 : 0.85)
		}
	}

	private applyPreset(id: GridPreset['id']) {
		const preset = this.presets.find((p) => p.id === id) ?? this.presets[0]
		this.cols = preset.cols
		this.rows = preset.rows
		this.mines = preset.mines
		this.cellSize = preset.cellSize

		this.computeLayout()
	}

	private computeLayout() {
		// Wir reservieren oben Platz für Titel/Info/Buttons.
		// Wenn die Buttons schon existieren, nehmen wir deren echte Position.
		if (this.presetButtons) {
			const anyBtn = this.presetButtons.desktop
			const buttonsBottom = anyBtn.y + anyBtn.height / 2
			this.boardOffsetY = Math.round(buttonsBottom + 18)
		} else {
			this.boardOffsetY = 115
		}

		const availableWidth = Math.max(1, this.scale.width - 20)
		const availableHeight = Math.max(1, this.scale.height - this.boardOffsetY - 20)

		// Falls das Preset nicht ins Canvas passt, Zellgröße runter skalieren.
		const maxCellFromWidth = Math.floor(availableWidth / this.cols)
		const maxCellFromHeight = Math.floor(availableHeight / this.rows)
		const maxCell = Math.max(12, Math.min(maxCellFromWidth, maxCellFromHeight))
		this.cellSize = Math.max(12, Math.min(this.cellSize, maxCell))

		const boardWidth = this.cols * this.cellSize
		this.boardOffsetX = Math.round((this.scale.width - boardWidth) / 2)
		this.boardOffsetX = Math.max(10, this.boardOffsetX)
	}

	private startNewGame() {
		this.gameOver = false

		// cleanup old
		for (const row of this.cellViews) {
			for (const v of row) {
				v.bg.destroy()
				v.label.destroy()
				v.flag.destroy()
			}
		}
		this.cellViews = []

		// Layout neu berechnen (falls Canvas/Scale inzwischen anders ist)
		this.computeLayout()

		this.board = new MinesweeperBoard({
			cols: this.cols,
			rows: this.rows,
			mines: this.mines
		})

		this.buildBoardView()
		this.statusText.setText('Minesweeper Rewired')
	}

	private buildBoardView() {
		for (let y = 0; y < this.rows; y++) {
			const row: CellView[] = []
			for (let x = 0; x < this.cols; x++) {
				const px = this.boardOffsetX + x * this.cellSize
				const py = this.boardOffsetY + y * this.cellSize

				const bg = this.add
					.rectangle(px, py, this.cellSize - 2, this.cellSize - 2, 0x1f2937)
					.setOrigin(0)
					.setStrokeStyle(1, 0x334155)
					.setInteractive({ useHandCursor: true })

				const label = this.add
					.text(px + this.cellSize / 2, py + this.cellSize / 2, '', {
						fontFamily: 'system-ui, -apple-system, Segoe UI, Roboto, Arial',
						fontSize: `${Math.max(12, Math.floor(this.cellSize * 0.55))}px`,
						color: '#e2e8f0'
					})
					.setOrigin(0.5)

				const flag = this.add
					.text(px + this.cellSize / 2, py + this.cellSize / 2, '', {
						fontFamily: 'system-ui, -apple-system, Segoe UI, Roboto, Arial',
						fontSize: `${Math.max(12, Math.floor(this.cellSize * 0.55))}px`,
						color: '#f97316'
					})
					.setOrigin(0.5)

				bg.on('pointerdown', (pointer: Phaser.Input.Pointer) => {
					if (this.gameOver) return
					if (pointer.rightButtonDown()) {
						this.onToggleFlag(x, y)
					} else {
						this.onReveal(x, y)
					}
				})

				row.push({ bg, label, flag })
			}
			this.cellViews.push(row)
		}

		this.redrawAll()
	}

	private onToggleFlag(x: number, y: number) {
		const changed = this.board.toggleFlag(x, y)
		if (!changed) return
		this.redrawCell(x, y)
	}

	private onReveal(x: number, y: number) {
		const res = this.board.reveal(x, y)
		this.applyRevealResult(res)
	}

	private applyRevealResult(res: RevealResult) {
		if (res.type === 'noop') return

		for (const p of res.revealed) {
			this.redrawCell(p.x, p.y)
		}

		if (res.type === 'mine') {
			this.gameOver = true
			this.statusText.setText('Boom! You lose. Press R to restart.')
		}

		if (res.type === 'win') {
			this.gameOver = true
			this.statusText.setText('You won! Press R for a new game.')
		}
	}

	private redrawAll() {
		for (let y = 0; y < this.rows; y++) {
			for (let x = 0; x < this.cols; x++) this.redrawCell(x, y)
		}
	}

	private redrawCell(x: number, y: number) {
		const cell = this.board.getCell(x, y)
		if (!cell) return
		const view = this.cellViews[y][x]
		const { bg, label, flag } = view

		label.setText('')
		flag.setText('')

		if (!cell.revealed) {
			bg.setFillStyle(0x1f2937)
			bg.setStrokeStyle(1, 0x334155)
			if (cell.flagged) flag.setText('⚑')
			return
		}

		bg.setFillStyle(0x0f172a)
		bg.setStrokeStyle(1, 0x475569)

		if (cell.isMine) {
			bg.setFillStyle(0x7f1d1d)
			label.setText('✹')
			label.setColor('#fecaca')
			return
		}

		if (cell.adjacentMines > 0) {
			label.setText(String(cell.adjacentMines))
			label.setColor(this.colorForNumber(cell.adjacentMines))
		}
	}

	private colorForNumber(n: number) {
		switch (n) {
			case 1:
				return '#60a5fa'
			case 2:
				return '#34d399'
			case 3:
				return '#f87171'
			case 4:
				return '#a78bfa'
			case 5:
				return '#fb923c'
			case 6:
				return '#22d3ee'
			default:
				return '#e2e8f0'
		}
	}
}
