export type Cell = {
	x: number
	y: number
	isMine: boolean
	adjacentMines: number
	revealed: boolean
	flagged: boolean
}

export type BoardConfig = {
	cols: number
	rows: number
	mines: number
	rng?: () => number
}

export type RevealResult =
	| { type: 'noop' }
	| { type: 'mine'; revealed: Array<{ x: number; y: number }> }
	| { type: 'revealed'; revealed: Array<{ x: number; y: number }> }
	| { type: 'win'; revealed: Array<{ x: number; y: number }> }

export default class MinesweeperBoard {
	readonly cols: number
	readonly rows: number
	readonly mines: number
	private readonly rng: () => number
	private cells: Cell[][]
	private placed = false
	private revealedSafeCount = 0

	constructor(cfg: BoardConfig) {
		this.cols = cfg.cols
		this.rows = cfg.rows
		this.mines = cfg.mines
		this.rng = cfg.rng ?? Math.random

		if (this.mines <= 0) throw new Error('mines must be > 0')
		if (this.cols <= 0 || this.rows <= 0) throw new Error('invalid board size')
		if (this.mines >= this.cols * this.rows) throw new Error('too many mines')

		this.cells = []
		for (let y = 0; y < this.rows; y++) {
			const row: Cell[] = []
			for (let x = 0; x < this.cols; x++) {
				row.push({
					x,
					y,
					isMine: false,
					adjacentMines: 0,
					revealed: false,
					flagged: false
				})
			}
			this.cells.push(row)
		}
	}

	getCell(x: number, y: number): Cell | undefined {
		if (x < 0 || y < 0 || x >= this.cols || y >= this.rows) return undefined
		return this.cells[y][x]
	}

	forEachCell(fn: (cell: Cell) => void) {
		for (let y = 0; y < this.rows; y++) {
			for (let x = 0; x < this.cols; x++) fn(this.cells[y][x])
		}
	}

	toggleFlag(x: number, y: number): boolean {
		const c = this.getCell(x, y)
		if (!c || c.revealed) return false
		c.flagged = !c.flagged
		return true
	}

	reveal(x: number, y: number): RevealResult {
		const start = this.getCell(x, y)
		if (!start) return { type: 'noop' }
		if (start.revealed || start.flagged) return { type: 'noop' }

		// First click: place mines so that the clicked cell is safe.
		if (!this.placed) {
			this.placeMinesAvoiding(x, y)
			this.computeAdjacencies()
			this.placed = true
		}

		if (start.isMine) {
			const revealed = this.revealAllMines()
			return { type: 'mine', revealed }
		}

		const revealed = this.floodReveal(start)

		if (this.revealedSafeCount === this.cols * this.rows - this.mines) {
			return { type: 'win', revealed }
		}

		return { type: 'revealed', revealed }
	}

	private neighbors(cell: Cell): Cell[] {
		const out: Cell[] = []
		for (let dy = -1; dy <= 1; dy++) {
			for (let dx = -1; dx <= 1; dx++) {
				if (dx === 0 && dy === 0) continue
				const n = this.getCell(cell.x + dx, cell.y + dy)
				if (n) out.push(n)
			}
		}
		return out
	}

	private placeMinesAvoiding(avoidX: number, avoidY: number) {
		const positions: Array<{ x: number; y: number }> = []
		for (let y = 0; y < this.rows; y++) {
			for (let x = 0; x < this.cols; x++) {
				if (x === avoidX && y === avoidY) continue
				positions.push({ x, y })
			}
		}

		// Fisher-Yates shuffle with rng
		for (let i = positions.length - 1; i > 0; i--) {
			const j = Math.floor(this.rng() * (i + 1))
			const tmp = positions[i]
			positions[i] = positions[j]
			positions[j] = tmp
		}

		for (let i = 0; i < this.mines; i++) {
			const p = positions[i]
			this.cells[p.y][p.x].isMine = true
		}
	}

	private computeAdjacencies() {
		this.forEachCell((c) => {
			if (c.isMine) {
				c.adjacentMines = 0
				return
			}
			const mines = this.neighbors(c).filter((n) => n.isMine).length
			c.adjacentMines = mines
		})
	}

	private floodReveal(start: Cell): Array<{ x: number; y: number }> {
		const revealed: Array<{ x: number; y: number }> = []
		const stack: Cell[] = [start]

		while (stack.length) {
			const c = stack.pop()!
			if (c.revealed || c.flagged) continue
			if (c.isMine) continue
			c.revealed = true
			this.revealedSafeCount++
			revealed.push({ x: c.x, y: c.y })

			if (c.adjacentMines === 0) {
				for (const n of this.neighbors(c)) {
					if (!n.revealed && !n.flagged && !n.isMine) stack.push(n)
				}
			}
		}

		return revealed
	}

	private revealAllMines(): Array<{ x: number; y: number }> {
		const revealed: Array<{ x: number; y: number }> = []
		this.forEachCell((c) => {
			if (c.isMine && !c.revealed) {
				c.revealed = true
				revealed.push({ x: c.x, y: c.y })
			}
		})
		return revealed
	}
}

